public void speak(final String text) {
    cancel();  // stop any current prompt
    Config.Policy policy = Config.policy(context);
    sink.log("── prompt (" + policy + "): " + text);
    if (ttsReady) {
        pendingText = text;
        File out = new File(context.getCacheDir(), "prompt.wav");
        out.delete();
        int r = tts.synthesizeToFile(text, null, out, "p-" + System.nanoTime());
        if (r == TextToSpeech.SUCCESS) return;
        sink.log("TTS synth request failed (" + r + "), using fallback tone");
    } else {
        sink.log("TTS not ready, using fallback tone");
    }
    play(fallbackToneFile());
}
