private void play(final File file) {
    final Config.Policy policy = Config.policy(context);
    main.post(() -> {
        releasePlayer(); // cancels previous
        try {
            applyPolicy(policy);
            MediaPlayer mp = new MediaPlayer();
            mp.setAudioAttributes(attrsFor(policy));
            mp.setDataSource(file.getAbsolutePath());
            mp.setVolume(gain(), gain());
            mp.setOnCompletionListener(p -> { sink.log("   done"); endPolicy(policy); releasePlayer(); notifyDone(); });
            mp.setOnErrorListener((p, what, extra) -> { sink.log("player error " + what + "/" + extra); endPolicy(policy); releasePlayer(); notifyDone(); return true; });
            mp.prepare();
            mp.start();
            sink.log("   playing via " + describe(policy));
            player = mp;
        } catch (IOException | RuntimeException e) {
            sink.log("playback failed: " + e);
            endPolicy(policy);
            releasePlayer();
            notifyDone();
        }
    });
}
