private File toneFile() {
    File f = new File(context.getCacheDir(), "prompt_tone.wav");
    if (f.length() > 1000) return f;
    int rate = 22050;
    double[][] seq = {{660, 0.14}, {0, 0.05}, {880, 0.18}};
    int total = 0; for (double[] s : seq) total += (int)(s[1]*rate);
    short[] pcm = new short[total];
    int pos = 0;
    for (double[] s : seq) {
        int n = (int)(s[1]*rate);
        for (int i = 0; i < n; i++) {
            double t = (double) i / rate;
            double env = Math.min(1.0, Math.min(i / (0.01*rate), (n - i) / (0.02*rate)));
            pcm[pos++] = (short) (Math.sin(2*Math.PI*s[0]*t) * 0.35 * 32767 * Math.max(0, env));
        }
    }
    writeWav(f, pcm, rate);
    return f;
}

private static void writeWav(File f, short[] pcm, int rate) {
    ByteBuffer bb = ByteBuffer.allocate(44 + pcm.length*2).order(ByteOrder.LITTLE_ENDIAN);
    bb.put("RIFF".getBytes(StandardCharsets.US_ASCII));
    bb.putInt(36 + pcm.length*2);
    bb.put("WAVE".getBytes(...)); bb.put("fmt ".getBytes()); bb.putInt(16); bb.putShort((short)1); bb.putShort((short)1);
    bb.putInt(rate); bb.putInt(rate*2); bb.putShort((short)2); bb.putShort((short)16);
    bb.put("data".getBytes()); bb.putInt(pcm.length*2);
    for (short s : pcm) bb.putShort(s);
    try (FileOutputStream out = new FileOutputStream(f)) { out.write(bb.array()); } catch (IOException e) { ... }
}
